def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the full-length divider.
    div = None
    for r in range(h):
        if all(v == 2 for v in grid[r]):
            div = ("h", r)
            break
    if div is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                div = ("v", c)
                break
    if div is None:
        return [row[:] for row in grid]

    bg = max(set(v for row in grid for v in row if v != 2),
             key=lambda x: sum(row.count(x) for row in grid))
    cells = {(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, 2)}
    if not cells:
        return [row[:] for row in grid]

    # Get the non-background object cells as connected components.
    comps = []
    while cells:
        seed = cells.pop()
        comp = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in cells:
                    cells.remove(p)
                    comp.add(p)
                    stack.append(p)
        comps.append(comp)
    obj = max(comps, key=len)

    out = [row[:] for row in grid]
    if div[0] == "v":
        dc = div[1]
        # Move the object toward the divider until its nearest edge is adjacent.
        direction = 1 if max(c for r, c in obj) < dc else -1
        edge = max(c for r, c in obj) if direction == 1 else min(c for r, c in obj)
        steps = max(0, abs(dc - edge) - 1)
        moved = {(r, c + direction * steps) for r, c in obj}
        for r, c in obj:
            out[r][c] = bg
        for r, c in moved:
            out[r][c] = grid[r][c - direction * steps]
        line_c = (min(c for r, c in moved) - 1 if direction == 1
                  else max(c for r, c in moved) + 1)
        if 0 <= line_c < w:
            for r in range(h):
                if r != div[1] or line_c != div[1]:
                    out[r][line_c] = 8
    else:
        dr = div[1]
        direction = 1 if max(r for r, c in obj) < dr else -1
        edge = max(r for r, c in obj) if direction == 1 else min(r for r, c in obj)
        steps = max(0, abs(dr - edge) - 1)
        moved = {(r + direction * steps, c) for r, c in obj}
        for r, c in obj:
            out[r][c] = bg
        for r, c in moved:
            out[r][c] = grid[r - direction * steps][c]
        line_r = (min(r for r, c in moved) - 1 if direction == 1
                  else max(r for r, c in moved) + 1)
        if 0 <= line_r < h:
            for c in range(w):
                out[line_r][c] = 8
    return out
